<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Throwable; use Pterodactyl\Models\Server; use Pterodactyl\Models\ApiKey; use Illuminate\Http\JsonResponse; use Illuminate\Support\Facades\Log; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Models\Dezerx\DiscordBotAlert; use Pterodactyl\Models\Dezerx\DiscordBotMember; use Pterodactyl\Services\Dezerx\DiscordBot\Style; use Pterodactyl\Services\Dezerx\Subdomains\SubdomainManager; use Pterodactyl\Services\Dezerx\DiscordBot\Preview; use Pterodactyl\Services\Dezerx\DiscordBot\Snapshot; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\BotSettings; use Pterodactyl\Services\Dezerx\DiscordBot\Views\Backups; use Pterodactyl\Services\Dezerx\DiscordBot\Views\ServerInfo; use Pterodactyl\Services\Dezerx\DiscordBot\Views\ControlPanel; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\GetServerRequest; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class DiscordController extends ClientApiController { private const SERVER_COMMANDS = ['controlpanel', 'power', 'command', 'backups', 'connect', 'activity', 'billing']; public function __invoke(GetServerRequest $request, Server $server): JsonResponse { if (!BotConfig::enabled() || !BotConfig::coversServer($server)) { throw new NotFoundHttpException(); } $user = $request->user(); $personal = BotConfig::personal(); $bot = $personal ? BotConfig::personalBot($user->id) : BotConfig::globalBot(); $member = DiscordBotMember::query()->where('user_id', $user->id)->first(); $keyActive = $member?->api_key_id !== null && ApiKey::query()->whereKey($member->api_key_id)->exists(); $shape = Snapshot::server($server, $user); $active = $bot === null ? array_keys(BotSettings::CATALOGUE) : BotSettings::active($bot); $commands = []; foreach (self::SERVER_COMMANDS as $name) { if (!in_array($name, $active, true)) { continue; } $meta = BotSettings::CATALOGUE[$name]; $commands[] = [ 'name' => $name, 'emoji' => $meta['emoji'], 'description' => $meta['description'], 'usage' => match ($name) { 'power' => "/power server:{$shape['id']} action:restart", 'command' => "/command server:{$shape['id']} command:say hello", default => "/{$name} server:{$shape['id']}", }, ]; } if (in_array('alerts', $active, true)) { $commands[] = [ 'name' => 'alerts', 'emoji' => BotSettings::CATALOGUE['alerts']['emoji'], 'description' => BotSettings::CATALOGUE['alerts']['description'], 'usage' => "/alerts add server:{$shape['id']} memory:90 offline:True", ]; } return new JsonResponse([ 'mode' => $personal ? 'personal' : 'global', 'identifier' => $shape['id'], 'ready' => $bot !== null && ($personal || $bot->canOAuth()), 'linked' => $personal ? $bot !== null : ($member !== null && $keyActive), 'bot' => $bot === null ? null : [ 'name' => $bot->name, 'avatar' => $bot->avatarUrl(), 'inviteUrl' => BotConfig::inviteUrl($bot), 'userInstallUrl' => BotConfig::all()['user_install'] ? BotConfig::userInstallUrl($bot) : null, ], 'member' => $member === null ? null : ['username' => $member->username, 'avatar' => $member->avatarUrl()], 'oauth' => [ 'available' => !$personal && $bot !== null && $bot->canOAuth(), 'connectUrl' => route('dezerx.discordbot.connect'), ], 'commands' => $commands, 'alerts' => DiscordBotAlert::query() ->where('user_id', $user->id) ->where('server_id', $server->id) ->orderBy('id') ->get() ->map(fn (DiscordBotAlert $alert) => [ 'id' => $alert->id, 'channelUrl' => 'https://discord.com/channels/' . $alert->guild_id . '/' . $alert->channel_id, 'cpu' => $alert->cpu, 'memory' => $alert->memory, 'disk' => $alert->disk, 'offline' => $alert->offline, 'cooldown' => $alert->cooldown, 'notifiedAt' => $alert->notified_at?->toAtomString(), 'lastError' => $alert->last_error, ]) ->all(), 'css' => Preview::css(), 'previews' => $this->previews($server, $shape, $bot, $active, $user), ]); } private function previews(Server $server, array $shape, ?DiscordBot $bot, array $active, $user): array { $display = $bot ?? new DiscordBot(['user_id' => $user->id, 'name' => BotConfig::panelName(), 'application_id' => '0']); $previous = Style::current(); $style = Style::for($bot); $out = []; Style::use($style, $active, $bot === null ? null : BotSettings::powerActions($bot)); try { if (in_array('controlpanel', $active, true)) { [$lines, $error] = Snapshot::console($server, $user, $style->consoleLines()); $out[] = [ 'key' => 'controlpanel', 'title' => '/controlpanel', 'html' => Preview::render(ControlPanel::compose($shape, Snapshot::live($server, $shape), $lines, $error), $display, false, 'controlpanel'), ]; } $backups = in_array('backups', $active, true) ? Snapshot::backups($server, $user) : null; if ($backups !== null) { $out[] = [ 'key' => 'backups', 'title' => '/backups', 'html' => Preview::render(Backups::composeList($shape, $backups, count($backups)), $display, false, 'backups'), ]; } if (in_array('connect', $active, true)) { $out[] = [ 'key' => 'connect', 'title' => '/connect', 'html' => Preview::render(ServerInfo::composeConnect($shape, SubdomainManager::recordsFor($server->id), $user->username), $display, false, 'connect'), ]; } } catch (Throwable $exception) { Log::warning('discord bot: a server preview failed', ['server' => $server->uuid, 'error' => $exception->getMessage()]); } finally { Style::use($previous, null); } return $out; } } 